# -*- coding: utf-8 -*-
import os
import time

from taf.playwright.core.exceptions import DownloadNotFound


class DownloadWatcher(object):
    """Helpers for Playwright downloads and backward-compatible file polling."""

    def __init__(self, page, download_dir=None):
        self.page = page
        self.download_dir = download_dir

    def run_and_save(self, action, suggested_name=None, timeout=60):
        with self.page.expect_download(timeout=int(float(timeout) * 1000)) as download_info:
            action()
        download = download_info.value
        filename = suggested_name or download.suggested_filename
        if not self.download_dir:
            return download.path()
        if not os.path.exists(self.download_dir):
            os.makedirs(self.download_dir)
        target = os.path.join(self.download_dir, filename)
        download.save_as(target)
        return target

    def wait_for_file(self, filename=None, suffix=None, timeout=60):
        if not self.download_dir:
            raise DownloadNotFound("download_dir is not configured")

        deadline = time.time() + float(timeout)
        while time.time() <= deadline:
            if os.path.exists(self.download_dir):
                for item in os.listdir(self.download_dir):
                    if filename and item == filename:
                        return os.path.join(self.download_dir, item)
                    if suffix and item.endswith(suffix):
                        return os.path.join(self.download_dir, item)
            time.sleep(0.2)

        raise DownloadNotFound(
            "No downloaded file found in {!r} for filename={!r}, suffix={!r}".format(
                self.download_dir, filename, suffix
            )
        )
